using System;

class Program
{
    static void Main()
    {
        // Floating-point rounding error
        double a = 0.1;
        double b = 0.2;
        double sum = a + b;
        Console.WriteLine(sum == 0.3);        // False!
        Console.WriteLine(sum.ToString("R"));   // 0.30000000000000004

        // decimal handles this correctly
        decimal m1 = 0.1m;
        decimal m2 = 0.2m;
        decimal mSum = m1 + m2;
        Console.WriteLine(mSum == 0.3m);        // True
        Console.WriteLine(mSum);                 // 0.3
    }
}

