using System;

// Define a custom value type with struct
public struct Point
{
    public int X { get; set; }
    public int Y { get; set; }

    // Constructor for convenient initialization
    public Point(int x, int y)
    {
        X = x;
        Y = y;
    }

    // Method on the struct
    public double DistanceFromOrigin()
    {
        return Math.Sqrt(X * X + Y * Y);
    }

    public override string ToString()
    {
        return $"({X}, {Y})";
    }
}

class Program
{
    static void Main()
    {
        // Initialize with constructor
        Point p1 = new Point(3, 4);
        Console.WriteLine(p1.DistanceFromOrigin()); // 5.0

        // Copy — this is a full copy, not a reference!
        Point p2 = p1;
        p2.X = 100;
        Console.WriteLine(p1); // (3, 4) — unchanged
        Console.WriteLine(p2); // (100, 4)
    }
}
